        .@".." => switch (role) {
            .@"left" => 1,
            .@"right" => 2,
            else => null,
        },
        .@"and" => switch (role) {
            .@"left" => 1,
            .@"right" => 2,
            else => null,
        },
        .@"or" => switch (role) {
            .@"left" => 1,
            .@"right" => 2,
            else => null,
        },
        .@"neg" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"not" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"move" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"read" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"write" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"clone" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"share" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"weak" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"optional" => switch (role) {
            .@"type" => 1,
            else => null,
        },
        .@"error_union" => switch (role) {
            .@"type" => 1,
            else => null,
        },
        .@"borrow_read" => switch (role) {
